            lambda: self.store.publish_policy_catalog(
                "tenant-a", self.rules, None
            ),
            lambda: self.store.publish_policy_catalog(
                "tenant-a", {"p": _rule("*", True, "r")}, {}
            ),
            lambda: self.store.publish_policy_catalog(
                "tenant-a",
